const EDGES=[[0,1],[1,2],[2,3],[3,4],[4,0],[0,2],[1,3],[2,4],[4,5],[5,6],[6,7],[7,8],[8,9],[9,5],[5,7],[6,8],[7,9]];
const NEI=Array.from({length:10},()=>[]);
EDGES.forEach(([a,b])=>{NEI[a].push(b);NEI[b].push(a);});
const initial=[0,0,1,2,0,0,2,1,3,4];
function init(){return {round:0,fav:initial.slice(),v:initial.map(f=>Array.from({length:5},(_,c)=>c===f?4:1)),personal:[1,1,1,1,1],queue:Array.from({length:10},()=>[0,0,0,0,0]),fired:Array.from({length:10},()=>[false,false,false,false,false]),countHistory:[],history:[],offered:[]};}
function counts(s){let c=[0,0,0,0,0];s.fav.forEach(i=>c[i]++);return c;}
function offers(s){const cnt=counts(s),rank=Array.from({length:5},(_,c)=>c).sort((a,b)=>(s.personal[b]+0.9*cnt[b])-(s.personal[a]+0.9*cnt[a])||a-b);
const recipe=[rank[0],rank[1],s.round%5];
return recipe.map((c,j)=>({c,to:[(s.round*2+j*3)%10,(s.round*2+j*3+1)%10]}));}
function step(s,a,p={decay:0.85,click:3,neighbor:0.7,auto:0.8,burst:1.5,margin:0.5}){const x=structuredClone(s),o=offers(s),ct=counts(s);let newv=s.v.map(v=>v.map(n=>n*p.decay));const lead=ct.indexOf(Math.max(...ct));
for(let i=0;i<10;i++){for(let c=0;c<5;c++){newv[i][c]+=p.neighbor*NEI[i].filter(n=>s.fav[n]===c).length+s.queue[i][c];} if(i===(s.round*3)%10||i===(s.round*3+1)%10)newv[i][lead]+=p.auto;}
x.personal=x.personal.map(n=>n*0.7);
if(a<3){const card=o[a];card.to.forEach(i=>newv[i][card.c]+=p.click);x.personal[card.c]+=2;}else{x.personal=x.personal.map(n=>n*0.25);}
x.v=newv;x.fav=newv.map((v,i)=>{const best=v.indexOf(Math.max(...v));return v[best]>=v[s.fav[i]]+p.margin?best:s.fav[i];});x.queue=Array.from({length:10},()=>[0,0,0,0,0]);
for(let i=0;i<10;i++)for(let c=0;c<5;c++)if(!x.fired[i][c]&&NEI[i].filter(n=>x.fav[n]===c).length>=3){x.queue[i][c]+=p.burst;x.fired[i][c]=true;}
x.round++;x.countHistory.push(counts(x));x.history.push(a);x.offered.push(o);
return x;
}
function win(s,type,target=3){const c=counts(s);if(type==='lead')return c[target]>=4&&c.every((x,i)=>i===target||c[target]>x);return s.countHistory.slice(-3).length===3&&s.countHistory.slice(-3).every(c=>Math.max(...c)<=4&&c.filter(n=>n>=2).length>=3);}

